/// <summary>
/// MPJ_21275_BackOrders
/// Extension of SalesTable form datasource of SalesLine
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTable, SalesLine))]
final class METSalesTableFormSalesLineDS_Extension
{
    
}

Method.Source:
    /// <summary>
    ///  COC of ItemModified method
    /// </summary>
    void itemIdModified()
    {
        InventItemSalesSetup    inventItemSalesSetup;      
        FormDataSource          datasourceInventDim      = this.formRun().dataSource(formDataSourceStr(SalesTable,InventDim)) as FormDataSource ;
        SalesLine               salesLine       = this.formRun().dataSource().cursor();
        InventDim               inventDimLoc    = datasourceInventDim.cursor();
        InventDim               inventDimSales;

        next itemIdModified();

        //MPJ_17845_PBMSProductMDRItemSite on 04 March 2022 by Sathish - Start
        select firstonly METSalesUnit from inventItemSalesSetup
            where inventItemSalesSetup.ItemId == salesLine.ItemId
                exists join inventDimSales
                    where inventDimSales.inventDimId == inventItemSalesSetup.InventDimId
                        &&  inventDimSales.InventSiteId == inventDimLoc.InventSiteId;

        salesLine.SalesUnit  = inventItemSalesSetup.METSalesUnit != '' ?
                               inventItemSalesSetup.METSalesUnit :
                               salesLine.SalesUnit;
        //MPJ_17845_PBMSProductMDRItemSite - End
    }

    /// <summary>
    /// Write the record
    /// </summary>
    void write()
    {
        FormDataSource metSalesLine_ds;
        METSalesLine metSalesLine;
        SalesLine metSalesLineLocal;

        next write();

        metSalesLine_ds = this.formRun().dataSource(formDataSourceStr(SalesTable, METSalesLine));
        if (metSalesLine_ds)
        {
            metSalesLineLocal = this.cursor();
            metSalesLine = metSalesLine_ds.cursor();
            metSalesLineLocal.metPackMETSalesLine(metSalesLine);
            //insert in correct order Parent, then extension
            metSalesLine.SysExtensionSerializerExtensionMap::insertAfterBaseTable(metSalesLineLocal);
        }
    }

    /// <summary>
    /// Provides notification when the focus moves to another record or item in the form.
    /// </summary>
    /// <param name = "_forceUpdate">Force update the records</param>
    /// <returns>Is focus moved or not</returns>
    public boolean leaveRecord(boolean _forceUpdate)
    {
        boolean ret;

        if (_forceUpdate)
        {
            ttsbegin;
        }

        ret = next leaveRecord(_forceUpdate);

        if (_forceUpdate)
        {
            ttscommit;
        }

        return ret;
    }
